#if os(iOS)
import Foundation
import Observation
import HanlinAgentCore
import HanlinChatCore
import HanlinChatUI
import HanlinHostContracts
import HanlinPresentationKit
import HanlinRichUI

/// One immutable, transient request from the native connection form. The nonce
/// binds the user's current-work consent to this exact endpoint/model/key
/// configuration without persisting or hashing a credential.
@MainActor
final class OtzariaHanlinConnectionRequest {
    let id = UUID()
    let configuration: HanlinChatModelConfiguration
    init(endpoint: String, modelID: String, credential: String) throws {
        configuration = try OtzariaHanlinChatSession.configuration(
            endpoint: endpoint, modelID: modelID, credential: credential)
    }
}


/// A bounded acceptance journal of original control flow. Every value is a fixed
/// enum or boolean; credentials, model/source text and session identities never
/// enter this schema. It cannot grant access or alter an original outcome.
@MainActor
enum OtzariaHanlinConnectionDiagnostic {
    enum Stage: String {
        case inputConsumed, connectEntered, connectRejected, requestValidated, readRequestValidated
        case readRequestReturned, connectFailed
        case carriedConfigureEntered, carriedConfigureRejected, carriedConfigurationMismatch
        case engineConstructed, configurationActivated, configurationCompleted, configureFailed
        case openEntered, openRejected, openIssued, openFailed, mountObserved
        case consentCaptureEntered, consentCaptured, closeRequested
        case dismissObserved, dismissAccepted, readReopenEntered
        case consentConsumeEntered, consentConsumed
        case sourceComparisonRejected, sourceValidationFailed
    }
    enum Reason: String {
        case none, cancelled, invalidArguments, invalidContext, staleContext
        case denied, duplicateInvocation, otherHostError, otherError
    }
    enum Flag: String {
        case closed, storageFailed, configured, connecting, hasOperation
        case allowRead, hasReadOffer, hasReadScope, credentialPresent
        case retired, hasPresentation, hasNativeSession, mounted, foreground
        case hasNavigationTask, matchingSession, isPresented, hasPendingReadReopen
        case preservingContinuation, hasConsent, hasConnection
        case sameBackend, sameMappingSource, sameMappingEpoch, sameWorkspaceProjection
        case sameReaderContent, sameReadSource, sameSelection, sameLocale
    }

    #if DEBUG && targetEnvironment(simulator)
    private static var boundNonce: String?
    private static var destination: URL?
    private static var events: [[String: Any]] = []
    private static var overflow = false
    #endif

    static func reason(for error: any Error) -> Reason {
        if error is CancellationError { return .cancelled }
        guard let error = error as? HanlinHostError else { return .otherError }
        switch error {
        case .invalidArguments: return .invalidArguments
        case .invalidContext: return .invalidContext
        case .staleContext: return .staleContext
        case .denied: return .denied
        case .duplicateInvocation: return .duplicateInvocation
        default: return .otherHostError
        }
    }


    /// Only the original one-use input consumer calls this after validating,
    /// consuming and applying that exact input. Existing evidence is preserved.
    static func beginOwnedLiveInput(nonce: String) {
        #if DEBUG && targetEnvironment(simulator)
        let environment = ProcessInfo.processInfo.environment
        guard boundNonce == nil,
              environment["OTZARIA_HANLIN_LIVE_PROVIDER_CASE"] == "1",
              environment["OTZARIA_HANLIN_LIVE_NONCE"] == nonce,
              UUID(uuidString: nonce)?.uuidString == nonce else { return }
        do {
            let directory = try FileManager.default.url(for: .documentDirectory,
                in: .userDomainMask, appropriateFor: nil, create: false)
            let file = directory.appendingPathComponent("otzaria-hanlin-connection-stages-" + nonce + ".json")
            let initial: [[String: Any]] = [[
                "sequence": 1, "stage": Stage.inputConsumed.rawValue,
                "reason": Reason.none.rawValue, "flags": [String: Bool](),
            ]]
            let data = try JSONSerialization.data(withJSONObject: [
                "schemaVersion": 1, "overflow": false, "events": initial,
            ], options: [.sortedKeys])
            try data.write(to: file, options: .withoutOverwriting)
            try FileManager.default.setAttributes([.posixPermissions: 0o600], ofItemAtPath: file.path)
            events = initial
            overflow = false
            destination = file
            boundNonce = nonce
        } catch {
            // Keep the original business flow and any preexisting evidence.
            // A missing/incomplete journal is not diagnostic success.
        }
        #endif
    }

    static func record(_ stage: Stage, reason: Reason = .none, flags: [Flag: Bool] = [:]) {
        #if DEBUG && targetEnvironment(simulator)
        let environment = ProcessInfo.processInfo.environment
        guard let boundNonce, let file = destination,
              environment["OTZARIA_HANLIN_LIVE_PROVIDER_CASE"] == "1",
              environment["OTZARIA_HANLIN_LIVE_NONCE"] == boundNonce else { return }
        if events.count < 96 && flags.count <= 9 {
            events.append([
                "sequence": events.count + 1,
                "stage": stage.rawValue,
                "reason": reason.rawValue,
                "flags": Dictionary(uniqueKeysWithValues: flags.map { ($0.key.rawValue, $0.value) }),
            ])
        } else { overflow = true }
        do {
            let data = try JSONSerialization.data(withJSONObject: [
                "schemaVersion": 1, "overflow": overflow, "events": events,
            ], options: [.sortedKeys])
            try data.write(to: file, options: .atomic)
            try FileManager.default.setAttributes([.posixPermissions: 0o600], ofItemAtPath: file.path)
        } catch {
            // Diagnostic I/O never changes the original action, error, guard or
            // cleanup. The collector reports a missing journal explicitly.
        }
        #endif
    }
}

/// Scene-owned presentation state around the original SDK session and engine.
/// The original Core/scene adapter remains the only source of host authority.
@MainActor @Observable
final class OtzariaHanlinChatSession: Identifiable {
    let identity: HanlinHostSession
    nonisolated var id: UUID { identity.id }
    private var draftRevision = UUID()
    private(set) var draft = "" {
        didSet {
            // Write identity is ephemeral and advances even for an explicit
            // same-string clear. History remains owned by the existing store.
            draftRevision = UUID()
            historyChanged()
        }
    }
    var selectedProfile: PresentationReference { didSet { historyChanged() } }
    private(set) var messages: [HanlinChatMessage] = []
    private(set) var messageStates: [UUID: MessageOpenUIStateStore] = [:]
    private(set) var activities: [Activity] = []
    private(set) var reasoning: [UUID: String] = [:]
    private(set) var sources: [OtzariaHanlinSourceLink] = []
    private(set) var isNavigating = false
    private(set) var isConfigured = false
    private(set) var isConnecting = false
    private(set) var isStreaming = false
    private(set) var errorMessage: String?
    let presentationDescriptor: HostPresentationDescriptor
    let currentWorkReadOffer: OtzariaHanlinCurrentWorkReadScope?
    let currentWorkReadScope: OtzariaHanlinCurrentWorkReadScope?
    private let requiredConfigurationID: UUID?

    typealias Activity = OtzariaHanlinToolActivity

    @ObservationIgnored private let host: OtzariaHanlinHostAdapter
    @ObservationIgnored private let validateOwner: @MainActor () throws -> Void
    @ObservationIgnored private let onClose: @MainActor () -> Void
    @ObservationIgnored private let onNavigate: @MainActor (URL) async throws -> Void
    @ObservationIgnored private let onConnectionConfigured: @MainActor (UUID) throws -> Void
    @ObservationIgnored private let onRequestReadConnection: @MainActor (OtzariaHanlinConnectionRequest, OtzariaHanlinCurrentWorkReadScope) throws -> Void
    @ObservationIgnored private let sourceDestination: @MainActor (HanlinHostResultEvent) throws -> URL?
    @ObservationIgnored private var pendingHostResults: [String: HanlinHostResultEvent] = [:]
    @ObservationIgnored private let store: OtzariaHanlinScopedConversationStore
    @ObservationIgnored private var historyRevision: UInt64?
    @ObservationIgnored private var storageFailed = false
    @ObservationIgnored private var isMutatingHistory = false
    @ObservationIgnored private var agent: HanlinAgentSession?
    @ObservationIgnored private var model: HanlinModelReference?
    @ObservationIgnored private var operation: Task<Void, Never>?
    @ObservationIgnored private var closed = false

    init(identity: HanlinHostSession, host: OtzariaHanlinHostAdapter,
         store: OtzariaHanlinScopedConversationStore,
         currentWorkReadOffer: OtzariaHanlinCurrentWorkReadScope? = nil,
         currentWorkReadScope: OtzariaHanlinCurrentWorkReadScope? = nil,
         requiredConfigurationID: UUID? = nil,
         onConnectionConfigured: @escaping @MainActor (UUID) throws -> Void = { _ in },
         onRequestReadConnection: @escaping @MainActor (OtzariaHanlinConnectionRequest, OtzariaHanlinCurrentWorkReadScope) throws -> Void = { _, _ in throw HanlinHostError.denied },
         sourceDestination: @escaping @MainActor (HanlinHostResultEvent) throws -> URL?,
         validateOwner: @escaping @MainActor () throws -> Void,
         onClose: @escaping @MainActor () -> Void,
         onNavigate: @escaping @MainActor (URL) async throws -> Void) throws {
        self.identity = identity; self.host = host; self.store = store; self.sourceDestination = sourceDestination
        self.validateOwner = validateOwner; self.onClose = onClose; self.onNavigate = onNavigate
        self.currentWorkReadOffer = currentWorkReadOffer; self.currentWorkReadScope = currentWorkReadScope
        self.requiredConfigurationID = requiredConfigurationID
        self.onConnectionConfigured = onConnectionConfigured; self.onRequestReadConnection = onRequestReadConnection
        guard (currentWorkReadScope == nil) == (requiredConfigurationID == nil) else { throw HanlinHostError.denied }
        let descriptor = try OpenUICatalogs.host(appID: identity.context.namespace.app, research: true)
        presentationDescriptor = descriptor
        selectedProfile = descriptor.defaultProfile
        if let (history, revision) = try store.history() {
            _ = try ProfileResolver.resolve(host: descriptor, conversationID: identity.conversationID,
                assignment: .init(conversationID: identity.conversationID, profile: history.selectedProfile))
            for snapshot in history.presentations.values {
                let original = try ProfileResolver.resolve(host: descriptor, conversationID: identity.conversationID,
                    assignment: .init(conversationID: identity.conversationID, profile: snapshot.profile.profile.reference))
                guard original == snapshot.profile else { throw HanlinHostError.invalidRecord }
            }
            historyRevision = revision
            draft = history.draft; selectedProfile = history.selectedProfile
            messages = history.messages; reasoning = history.reasoning; sources = history.sources
            activities = history.activities.map {
                var value = $0
                if value.isActive { value.isActive = false; value.status = String(localized: "Interrupted") }
                return value
            }
            for (id, snapshot) in history.presentations { messageStates[id] = MessageOpenUIStateStore(snapshot: snapshot) }
        }
        for state in messageStates.values { observe(state) }
    }

    private func observe(_ state: MessageOpenUIStateStore) {
        state.onChange = { [weak self] _ in self?.historyChanged() }
    }

    private func checkpoint() throws {
        // Merely opening the native conversation picker does not create an
        // empty saved chat. A user draft, message or appearance choice does.
        if historyRevision == nil, draft.isEmpty, messages.isEmpty,
           selectedProfile == presentationDescriptor.defaultProfile { return }
        let history = OtzariaHanlinHistory(draft: draft, selectedProfile: selectedProfile, messages: messages,
            presentations: messageStates.mapValues(\.snapshot), activities: activities, reasoning: reasoning, sources: sources)
        historyRevision = try store.saveHistory(history, replacing: historyRevision)
    }

    private func historyChanged() {
        guard !closed, !storageFailed, !isMutatingHistory else { return }
        do { try checkpoint() }
        catch {
            storageFailed = true
            operation?.cancel()
            errorMessage = String(localized: "The conversation could not be saved. Close and reopen it before continuing; the previous saved conversation is preserved.")
        }
    }

    /// A live read of this presentation's original draft owner, never a render snapshot.
    func readCurrentDraftTextState() -> NativeMultilineTextEditor.TextState? {
        guard !closed else { return nil }
        do { try validateOwner() }
        catch { return nil }
        return .init(ownerID: identity.id, revision: draftRevision, text: draft)
    }

    /// A retained native callback cannot write after this original owner is revoked.
    func updateDraftFromEditor(_ value: String) {
        guard !storageFailed, readCurrentDraftTextState() != nil else { return }
        draft = value
    }

    var canSend: Bool {
        isConfigured && !closed && !storageFailed && !isStreaming && !isConnecting && !isNavigating
            && !draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            && draft.utf8.count <= 32_768 && messages.count <= 254
    }

    var profile: ResolvedPresentationProfile? {
        try? ProfileResolver.resolve(host: presentationDescriptor, conversationID: identity.conversationID,
            assignment: .init(conversationID: identity.conversationID, profile: selectedProfile))
    }

    private func requireCurrent() async throws {
        guard !closed else { throw HanlinHostError.staleContext }
        try validateOwner()
        let current = try await host.context(for: identity)
        try Task.checkCancellation()
        guard !closed, current == identity.context else { throw HanlinHostError.staleContext }
        try validateOwner()
    }

    /// Explicit native input only. Reading is OFF unless this exact connection
    /// form action requests the displayed current work. That action only queues
    /// a source-bound dismissal/reopen; it never sends a model message.
    func configure(endpoint: String, modelID: String, credential: String, allowCurrentWorkRead: Bool = false) {
        OtzariaHanlinConnectionDiagnostic.record(.connectEntered, flags: [
            .closed: closed, .storageFailed: storageFailed, .configured: isConfigured,
            .connecting: isConnecting, .hasOperation: operation != nil,
            .allowRead: allowCurrentWorkRead, .hasReadOffer: currentWorkReadOffer != nil,
            .hasReadScope: currentWorkReadScope != nil, .credentialPresent: !credential.isEmpty,
        ])
        guard !closed, !storageFailed, !isConfigured, !isConnecting, operation == nil else {
            OtzariaHanlinConnectionDiagnostic.record(.connectRejected)
            return
        }
        do {
            let request = try OtzariaHanlinConnectionRequest(endpoint: endpoint, modelID: modelID, credential: credential)
            OtzariaHanlinConnectionDiagnostic.record(.requestValidated)
            if allowCurrentWorkRead {
                guard currentWorkReadScope == nil, let offer = currentWorkReadOffer else { throw HanlinHostError.denied }
                try validateOwner()
                OtzariaHanlinConnectionDiagnostic.record(.readRequestValidated)
                try onRequestReadConnection(request, offer)
                OtzariaHanlinConnectionDiagnostic.record(.readRequestReturned, flags: [.closed: closed])
            } else {
                configure(request)
            }
        } catch {
            OtzariaHanlinConnectionDiagnostic.record(.connectFailed, reason: OtzariaHanlinConnectionDiagnostic.reason(for: error))
            if !closed { errorMessage = String(localized: "The connection could not be configured. Check the address, model and key.") }
        }
    }

    /// Only the original owner may carry the same immutable request through an
    /// actual sheet dismissal. A different request cannot reuse its read grant.
    func configure(_ request: OtzariaHanlinConnectionRequest) {
        OtzariaHanlinConnectionDiagnostic.record(.carriedConfigureEntered, flags: [
            .closed: closed, .storageFailed: storageFailed, .configured: isConfigured,
            .connecting: isConnecting, .hasOperation: operation != nil,
            .hasReadScope: currentWorkReadScope != nil,
        ])
        guard !closed, !storageFailed, !isConfigured, !isConnecting, operation == nil else {
            OtzariaHanlinConnectionDiagnostic.record(.carriedConfigureRejected)
            return
        }
        guard requiredConfigurationID == nil || requiredConfigurationID == request.id else {
            OtzariaHanlinConnectionDiagnostic.record(.carriedConfigurationMismatch)
            onClose(); return
        }
        isConnecting = true
        operation = Task { @MainActor [weak self] in
            guard let self else { return }
            defer { self.isConnecting = false; self.operation = nil }
            do {
                try Task.checkCancellation()
                try self.validateOwner()
                let configuration = request.configuration
                let engine = try HanlinAISDKAgentEngine(configuration: configuration,
                    fetch: HanlinAISDKProviderFactory.makeFetch(sessionConfiguration: .ephemeral))
                OtzariaHanlinConnectionDiagnostic.record(.engineConstructed)
                try self.onConnectionConfigured(request.id)
                OtzariaHanlinConnectionDiagnostic.record(.configurationActivated)
                try await self.requireCurrent()
                let session = HanlinAgentSession(identity: self.identity, host: self.host, engine: engine, store: self.store)
                session.onHostResult = { [weak self] event in
                    guard let self, !self.closed, self.isStreaming, event.call.session == self.identity else { return }
                    let key = event.call.runID.uuidString + ":" + event.call.providerCallID
                    guard self.pendingHostResults.count < 256 else { self.operation?.cancel(); return }
                    self.pendingHostResults[key] = event
                }
                session.onSessionInvalidated = { [weak self] _ in
                    guard let self, !self.closed else { return }
                    self.onClose()
                }
                self.agent = session
                self.model = .init(provider: HanlinAISDKProviderFactory.descriptor(for: configuration).kind.rawValue,
                                   modelID: configuration.baseModelID)
                self.isConfigured = true
                self.errorMessage = nil
                OtzariaHanlinConnectionDiagnostic.record(.configurationCompleted)
            } catch {
                OtzariaHanlinConnectionDiagnostic.record(.configureFailed,
                    reason: OtzariaHanlinConnectionDiagnostic.reason(for: error))
                if !self.closed {
                    self.errorMessage = String(localized: "The connection could not be configured. Check the address, model and key.")
                    // A failed granted connection cannot be retried with a new
                    // endpoint/key while retaining the previous user's consent.
                    if self.currentWorkReadScope != nil { self.onClose() }
                }
            }
        }
    }

    static func configuration(endpoint: String, modelID: String, credential: String) throws -> HanlinChatModelConfiguration {
        let model = modelID.trimmingCharacters(in: .whitespacesAndNewlines)
        guard let url = URL(string: endpoint.trimmingCharacters(in: .whitespacesAndNewlines)),
              url.scheme == "https", let host = url.host, !host.isEmpty,
              url.user == nil, url.password == nil, url.query == nil, url.fragment == nil,
              !model.isEmpty, model.utf8.count <= 128, !credential.isEmpty, credential.utf8.count <= 4_096 else {
            throw HanlinHostError.invalidArguments
        }
        return .init(modelID: model, company: "OPENAI", apiType: "OpenAI", endpoint: url,
                     apiKey: credential, supportsToolUse: true)
    }

    func send() {
        guard canSend, let agent, let model, let profile else { return }
        let prompt = draft
        isMutatingHistory = true
        defer { isMutatingHistory = false }
        draft = ""
        messages.append(.user(prompt))
        let history = messages.map { HanlinAISDKMessage(role: $0.role == "user" ? .user : .assistant, text: $0.content) }
        let answerID = UUID()
        messages.append(.init(id: answerID, role: "assistant", content: ""))
        let messageIdentity = PresentationMessageIdentity(appID: identity.context.namespace.app,
            conversationID: identity.conversationID, messageID: answerID)
        messageStates[answerID] = MessageOpenUIStateStore(snapshot: .init(identity: messageIdentity, profile: profile))
        if let state = messageStates[answerID] { observe(state) }
        do { try checkpoint() }
        catch {
            messages.removeLast(2); messageStates[answerID] = nil
            storageFailed = true; draft = prompt
            errorMessage = String(localized: "The message could not be saved, so it was not sent. Close and reopen this conversation.")
            return
        }
        pendingHostResults.removeAll()
        isStreaming = true
        errorMessage = nil
        operation = Task { @MainActor [weak self] in
            guard let self else { return }
            defer { self.isStreaming = false; self.operation = nil }
            do {
                try await self.requireCurrent()
                let readInstructions = try self.currentWorkReadScope?.modelInstructions()
                    ?? "This conversation has no permission to read a book or selection or modify library data."
                let instructions = OpenUICatalogs.instructions(for: profile)
                    + "\nUse only the host's current advertised catalog. " + readInstructions
                    + " Do not invent citations or application actions."
                let stream = try await agent.stream(messages: history, systemPrompt: instructions,
                    modelReference: model, maxSteps: 8, presentationReference: profile.profile.reference.key)
                for try await event in stream {
                    try Task.checkCancellation()
                    try await self.requireCurrent()
                    guard event.session == self.identity else { throw HanlinHostError.staleContext }
                    try self.receive(event.event, messageID: answerID, runID: event.runID)
                    try self.checkpoint()
                }
            } catch {
                if !self.closed {
                    self.errorMessage = Task.isCancelled
                        ? String(localized: "The response was stopped.")
                        : String(localized: "The request could not be completed. The original conversation context may have changed.")
                }
            }
            for index in self.activities.indices where self.activities[index].messageID == answerID && self.activities[index].isActive {
                self.activities[index].isActive = false
                self.activities[index].status = String(localized: "Stopped")
            }
            self.pendingHostResults.removeAll()
            if !self.closed { self.historyChanged() }
        }
    }

    private func receive(_ event: HanlinAISDKStreamEvent, messageID: UUID, runID: UUID) throws {
        switch event {
        case .textDelta(let delta):
            guard let index = messages.firstIndex(where: { $0.id == messageID }),
                  messages[index].content.utf8.count + delta.utf8.count <= 262_144 else { throw HanlinHostError.outputLimitExceeded }
            messages[index].content += delta
        case .reasoningDelta(let delta):
            let prior = reasoning[messageID] ?? ""
            guard prior.utf8.count + delta.utf8.count <= 262_144 else { throw HanlinHostError.outputLimitExceeded }
            reasoning[messageID] = prior + delta
        case .toolCall(let call):
            guard call.argumentsJSON.utf8.count <= 65_536, activities.count < 256 else { throw HanlinHostError.outputLimitExceeded }
            if let index = activities.firstIndex(where: { $0.id == call.id && $0.messageID == messageID }) {
                activities[index].arguments = call.argumentsJSON
            } else {
                activities.append(.init(id: call.id, messageID: messageID, name: call.name,
                    status: String(localized: "Running"), arguments: call.argumentsJSON, isActive: true))
            }
        case .toolResult(let callID, let name, let text, _, let isError):
            guard text.utf8.count <= 262_144 else { throw HanlinHostError.outputLimitExceeded }
            guard let index = activities.firstIndex(where: { $0.id == callID && $0.messageID == messageID }) else { return }
            activities[index].name = name
            activities[index].status = isError ? String(localized: "Failed") : String(localized: "Completed")
            activities[index].result = text
            activities[index].isActive = false
            let resultKey = runID.uuidString + ":" + callID
            if let original = pendingHostResults.removeValue(forKey: resultKey), !isError,
               let destination = try sourceDestination(original) {
                guard sources.count < 256 else { throw HanlinHostError.outputLimitExceeded }
                sources.append(.init(id: original.resultID, messageID: messageID, destination: destination))
            }
        case .toolOutputDenied(let callID, _):
            if let index = activities.firstIndex(where: { $0.id == callID && $0.messageID == messageID }) {
                activities[index].status = String(localized: "Denied"); activities[index].isActive = false
            }
        case .file, .structuredPart:
            // These require an original host media/structured-action owner;
            // do not silently display an empty successful answer or invent one.
            throw HanlinHostError.unsupportedProviderCapability
        default: break
        }
    }

    func stop() { operation?.cancel() }

    func requestNavigation(_ url: URL) {
        guard !closed, !isStreaming, !isConnecting, !isNavigating, operation == nil else { return }
        isNavigating = true
        operation = Task { @MainActor [weak self] in
            guard let self else { return }
            defer { self.operation = nil; self.isNavigating = false }
            do { try await self.requireCurrent(); try await self.onNavigate(url) }
            catch { if !self.closed { self.errorMessage = String(localized: "This source could not be opened in the original window.") } }
        }
    }

    func close() { onClose() }

    /// Revocation is synchronous before async SDK cancellation or sheet dismissal.
    func revoke() {
        guard !closed else { return }
        closed = true
        // Mutations already checkpoint through this exact lease. Flush once
        // while it is still current, then revoke before asynchronous SDK work.
        if !storageFailed { try? checkpoint() }
        store.revoke()
        operation?.cancel(); operation = nil
        let prior = agent
        agent = nil; model = nil
        draft = ""; messages.removeAll(); messageStates.removeAll(); activities.removeAll(); reasoning.removeAll(); sources.removeAll()
        pendingHostResults.removeAll()
        isConfigured = false; isConnecting = false; isStreaming = false; isNavigating = false
        Task { await prior?.invalidate() }
    }
}
#endif

#if os(iOS)
import Foundation
import Observation
import SwiftUI
import HanlinHostContracts
import HanlinAgentCore
import OtzariaUIRouting

/// A source click retains one original host identity through actual dismissal.
/// Its dispatcher performs the context transition after the covering sheet is gone.
@MainActor
final class OtzariaHanlinNavigationHandoff {
    let destination: HanlinHostDestination
    let session: HanlinHostSession
    let host: OtzariaHanlinHostAdapter
    var requestID: UUID { destination.requestID }
    private var action: (@MainActor () async throws -> HanlinHostNavigationReceipt)?
    private let closeOriginal: @MainActor () -> Void
    init(destination: HanlinHostDestination, session: HanlinHostSession,
         host: OtzariaHanlinHostAdapter, closeOriginal: @escaping @MainActor () -> Void) {
        self.destination = destination; self.session = session; self.host = host
        self.closeOriginal = closeOriginal
        let dispatcher = HanlinHostDispatcher(host: host)
        action = { try await dispatcher.openWithContextTransition(destination, session: session) }
    }
    func consume() async throws -> HanlinHostNavigationReceipt {
        guard let action else { throw HanlinHostError.duplicateInvocation }
        self.action = nil
        try Task.checkCancellation()
        return try await action()
    }
    func cancel() { action = nil; closeOriginal() }
}

@MainActor @Observable
final class OtzariaHanlinChatOwner {
    private(set) var presentation: OtzariaHanlinChatSession?
    private(set) var isPresented = false
    private(set) var navigationReceipt: HanlinHostNavigationReceipt?
    @ObservationIgnored private weak var manager: iOSNavigationManager?
    @ObservationIgnored private weak var nativeSession: MaktabahNativeSceneSession?
    @ObservationIgnored private let composition: MaktabahNativeRoutingComposition
    @ObservationIgnored private var host: OtzariaHanlinHostAdapter?
    @ObservationIgnored private var presentedSceneID: String?
    @ObservationIgnored private var pendingNavigation: OtzariaHanlinNavigationHandoff?
    @ObservationIgnored private var pendingHistory: (namespace: HanlinConversationNamespace, id: UUID)?
    private struct ReadReopen {
        let originalSessionID: UUID
        let namespace: HanlinConversationNamespace
        let conversationID: UUID
        let consent: MaktabahNativeRoutingComposition.HanlinReadConsent?
        let connection: OtzariaHanlinConnectionRequest?
    }
    @ObservationIgnored private var pendingReadReopen: ReadReopen?
    @ObservationIgnored private var connectionAfterMount: (sessionID: UUID, request: OtzariaHanlinConnectionRequest)?
    @ObservationIgnored private let conversations = OtzariaHanlinConversationStore.shared
    @ObservationIgnored private var navigationTask: Task<Void, Never>?
    @ObservationIgnored private var retired = false

    init(manager: iOSNavigationManager, session: MaktabahNativeSceneSession,
         composition: MaktabahNativeRoutingComposition) {
        self.manager = manager; nativeSession = session; self.composition = composition
    }

    func open(conversationID: UUID? = nil, expectedNamespace: HanlinConversationNamespace? = nil) {
        openConversation(conversationID: conversationID, expectedNamespace: expectedNamespace, readReopen: nil)
    }

    private func openConversation(conversationID: UUID?, expectedNamespace: HanlinConversationNamespace?, readReopen: ReadReopen?) {
        OtzariaHanlinConnectionDiagnostic.record(.openEntered, flags: [
            .retired: retired, .hasPresentation: presentation != nil,
            .hasNavigationTask: navigationTask != nil, .hasNativeSession: nativeSession != nil,
            .mounted: nativeSession?.mounted == true, .foreground: nativeSession?.foreground == true,
            .hasConsent: readReopen?.consent != nil, .hasConnection: readReopen?.connection != nil,
        ])
        guard !retired, presentation == nil, navigationTask == nil,
              let manager, let nativeSession, nativeSession.mounted, nativeSession.foreground else {
            OtzariaHanlinConnectionDiagnostic.record(.openRejected)
            return
        }
        var issued: HanlinHostSession?
        do {
            let readConnection: (consent: MaktabahNativeRoutingComposition.HanlinReadConsent, dismissedSessionID: UUID, configurationID: UUID)?
            if let readReopen, let consent = readReopen.consent, let connection = readReopen.connection {
                readConnection = (consent, readReopen.originalSessionID, connection.id)
            } else { readConnection = nil }
            let prepared = try composition.makeHanlinHostSession(manager: manager, conversationID: conversationID ?? UUID(),
                readConnection: readConnection) { [weak self] in
                self?.requestClose()
            }
            issued = prepared.session
            let identity = prepared.session
            if let expectedNamespace {
                guard identity.context.namespace == expectedNamespace else { throw HanlinHostError.staleContext }
                if readReopen == nil {
                    guard try conversations.history(identity.conversationID, namespace: expectedNamespace) != nil else {
                        throw HanlinHostError.staleContext
                    }
                }
            }
            let sessionID = identity.id
            let scopedStore = OtzariaHanlinScopedConversationStore(identity: identity, store: conversations) { [weak self] in
                guard let self, !self.retired, let nativeSession = self.nativeSession,
                      nativeSession.mounted, nativeSession.foreground else { throw HanlinHostError.staleContext }
                try self.composition.validateHanlinHostSession(identity)
            }
            let readScope = try composition.hanlinCurrentWorkReadScope(for: identity)
            let readOffer = try? composition.hanlinCurrentWorkReadOffer(manager: manager, session: identity)
            let value = try OtzariaHanlinChatSession(identity: identity, host: prepared.host, store: scopedStore,
                currentWorkReadOffer: readOffer, currentWorkReadScope: readScope,
                requiredConfigurationID: readScope == nil ? nil : readReopen?.connection?.id,
                onConnectionConfigured: { [weak self] configurationID in
                    guard let self else { throw HanlinHostError.staleContext }
                    try self.validate(sessionID)
                    try self.composition.hanlinConnectionConfigured(configurationID, session: identity)
                }, onRequestReadConnection: { [weak self] request, scope in
                    guard let self else { throw HanlinHostError.staleContext }
                    try self.requestReadConnection(request, displayedScope: scope, sessionID: sessionID)
                },
                sourceDestination: { [weak self] event in
                    guard let self else { throw HanlinHostError.staleContext }
                    return try self.composition.hanlinSourceDestination(event, session: identity)
                }, validateOwner: { [weak self] in
                    guard let self else { throw HanlinHostError.staleContext }
                    try self.validate(sessionID)
                }, onClose: { [weak self] in self?.requestClose(sessionID: sessionID) },
                onNavigate: { [weak self] url in
                    guard let self else { throw HanlinHostError.staleContext }
                    try await self.queueNavigation(url, sessionID: sessionID)
                })
            try nativeSession.beginStudyChatPresentation(sessionID)
            host = prepared.host; presentation = value; presentedSceneID = nil; isPresented = true
            if let connection = readReopen?.connection {
                connectionAfterMount = (sessionID, connection)
            }
            OtzariaHanlinConnectionDiagnostic.record(.openIssued, flags: [.hasReadScope: readScope != nil])
        } catch {
            OtzariaHanlinConnectionDiagnostic.record(.openFailed,
                reason: OtzariaHanlinConnectionDiagnostic.reason(for: error))
            readReopen?.consent?.revoke()
            connectionAfterMount = nil
            if let issued {
                nativeSession.finishStudyChatPresentation(issued.id)
                composition.closeHanlinHostSession(issued)
            }
            manager.alertMessage = .init(title: String(localized: "Study chat unavailable"),
                message: String(localized: "The original study window is not ready. Try again from the reader."))
        }
    }

    func didMount(sceneID: String, sessionID: UUID) {
        OtzariaHanlinConnectionDiagnostic.record(.mountObserved, flags: [
            .matchingSession: presentation?.id == sessionID, .isPresented: isPresented,
            .retired: retired, .hasNativeSession: nativeSession != nil,
        ])
        guard presentation?.id == sessionID, isPresented, !retired else { return }
        guard let nativeSession, sceneID == nativeSession.sceneID.rawValue else {
            requestClose(sessionID: sessionID); return
        }
        presentedSceneID = sceneID
        if let pending = connectionAfterMount, pending.sessionID == sessionID {
            connectionAfterMount = nil
            presentation?.configure(pending.request)
        }
    }

    private func validate(_ sessionID: UUID) throws {
        guard !retired, isPresented, let presentation, presentation.id == sessionID,
              let nativeSession, nativeSession.mounted, nativeSession.foreground,
              presentedSceneID == nativeSession.sceneID.rawValue else { throw HanlinHostError.staleContext }
        try composition.validateHanlinHostSession(presentation.identity)
    }

    private func queueNavigation(_ url: URL, sessionID: UUID) async throws {
        try validate(sessionID)
        guard pendingNavigation == nil, pendingHistory == nil, pendingReadReopen == nil, navigationTask == nil,
              let host, let presentation else { throw HanlinHostError.duplicateInvocation }
        let destination = HanlinHostDestination(context: presentation.identity.context, objectReference: url.absoluteString)
        let response = try await host.open(destination)
        try response.validate(for: destination)
        guard case .queued = response else { throw HanlinHostError.resultMismatch }
        try validate(sessionID)
        let identity = presentation.identity
        pendingNavigation = .init(destination: destination, session: identity, host: host) { [weak self] in
            self?.composition.closeHanlinHostSession(identity)
        }
        requestClose(sessionID: sessionID, preservingContinuation: true)
    }

    func history() throws -> [OtzariaHanlinConversationSummary] {
        guard let presentation else { throw HanlinHostError.staleContext }
        try validate(presentation.id)
        return try conversations.summaries(namespace: presentation.identity.context.namespace)
    }

    func selectHistory(_ id: UUID) throws {
        guard let presentation, pendingNavigation == nil, pendingHistory == nil, pendingReadReopen == nil,
              navigationTask == nil else { throw HanlinHostError.staleContext }
        try validate(presentation.id)
        let namespace = presentation.identity.context.namespace
        guard try conversations.history(id, namespace: namespace) != nil else { throw HanlinHostError.invalidRecord }
        pendingHistory = (namespace, id)
        requestClose(sessionID: presentation.id, preservingContinuation: true)
    }

    func deleteHistory(_ summary: OtzariaHanlinConversationSummary) throws {
        guard let presentation, summary.id != presentation.identity.conversationID else { throw HanlinHostError.denied }
        try validate(presentation.id)
        try conversations.deleteConversation(summary, namespace: presentation.identity.context.namespace)
    }

    /// Called only by the native connection form after the user confirms the
    /// displayed work and supplies the exact immutable model configuration.
    private func requestReadConnection(_ request: OtzariaHanlinConnectionRequest,
        displayedScope: OtzariaHanlinCurrentWorkReadScope, sessionID: UUID) throws {
        OtzariaHanlinConnectionDiagnostic.record(.consentCaptureEntered)
        try validate(sessionID)
        guard let presentation, let manager, !presentation.isConfigured,
              !presentation.isConnecting, !presentation.isStreaming,
              pendingNavigation == nil, pendingHistory == nil, pendingReadReopen == nil,
              navigationTask == nil else { throw HanlinHostError.denied }
        let consent = try composition.makeHanlinCurrentWorkReadConsent(manager: manager,
            session: presentation.identity, displayedScope: displayedScope, configurationID: request.id) { [weak self] in
                self?.requestClose(sessionID: sessionID)
            }
        pendingReadReopen = .init(originalSessionID: sessionID, namespace: presentation.identity.context.namespace,
            conversationID: presentation.identity.conversationID, consent: consent, connection: request)
        OtzariaHanlinConnectionDiagnostic.record(.consentCaptured)
        requestClose(sessionID: sessionID, preservingContinuation: true)
    }

    /// Revocation cancels the original stream now, before asynchronous SDK
    /// invalidation or sheet dismissal. No connection/key follows the reopen.
    func endCurrentWorkReadAccess(sessionID: UUID) {
        guard let presentation, presentation.id == sessionID, presentation.currentWorkReadScope != nil else { return }
        do {
            try validate(sessionID)
            guard pendingNavigation == nil, pendingHistory == nil, pendingReadReopen == nil,
                  navigationTask == nil else { throw HanlinHostError.staleContext }
            pendingReadReopen = .init(originalSessionID: sessionID, namespace: presentation.identity.context.namespace,
                conversationID: presentation.identity.conversationID, consent: nil, connection: nil)
            requestClose(sessionID: sessionID, preservingContinuation: true)
        } catch { requestClose(sessionID: sessionID) }
    }

    /// A programmatic dismissal already owns its continuation. SwiftUI echoing
    /// false must not cancel the native handoff or the selected history reopen.
    func presentationBindingChanged(_ value: Bool, sessionID: UUID?) {
        guard let sessionID, presentation?.id == sessionID else { return }
        if !value && isPresented { requestClose(sessionID: sessionID) }
    }

    func requestClose(sessionID: UUID? = nil, preservingContinuation: Bool = false) {
        OtzariaHanlinConnectionDiagnostic.record(.closeRequested, flags: [
            .hasPresentation: presentation != nil,
            .matchingSession: presentation != nil && (sessionID == nil || presentation?.id == sessionID),
            .preservingContinuation: preservingContinuation, .hasPendingReadReopen: pendingReadReopen != nil,
        ])
        guard let presentation, sessionID == nil || presentation.id == sessionID else { return }
        if !preservingContinuation {
            pendingNavigation?.cancel(); pendingNavigation = nil; pendingHistory = nil
            pendingReadReopen?.consent?.revoke(); pendingReadReopen = nil
        }
        connectionAfterMount = nil
        isPresented = false; presentedSceneID = nil
        presentation.revoke()
        if pendingNavigation == nil { composition.closeHanlinHostSession(presentation.identity) }
        host = nil
    }

    /// SwiftUI calls this after the actual owned sheet finishes dismissing.
    /// A replacement cannot be opened while that old presentation is retained.
    func didDismiss(sessionID: UUID?) {
        OtzariaHanlinConnectionDiagnostic.record(.dismissObserved, flags: [
            .hasPresentation: presentation != nil,
            .matchingSession: sessionID != nil && presentation?.id == sessionID,
            .isPresented: isPresented, .hasPendingReadReopen: pendingReadReopen != nil,
        ])
        // A superseded SwiftUI callback has no ownership over this sheet or its
        // pending grant, even if the current sheet is itself already dismissing.
        guard let sessionID, let current = presentation, current.id == sessionID, !isPresented else { return }
        OtzariaHanlinConnectionDiagnostic.record(.dismissAccepted)
        current.revoke()
        if pendingNavigation == nil { composition.closeHanlinHostSession(current.identity) }
        nativeSession?.finishStudyChatPresentation(sessionID)
        presentation = nil; host = nil; isPresented = false; presentedSceneID = nil
        connectionAfterMount = nil
        if let readReopen = pendingReadReopen {
            pendingReadReopen = nil
            guard !retired, readReopen.originalSessionID == sessionID else {
                readReopen.consent?.revoke(); return
            }
            OtzariaHanlinConnectionDiagnostic.record(.readReopenEntered, flags: [
                .hasConsent: readReopen.consent != nil, .hasConnection: readReopen.connection != nil,
            ])
            openConversation(conversationID: readReopen.conversationID,
                expectedNamespace: readReopen.namespace, readReopen: readReopen)
            return
        }
        if !retired, let history = pendingHistory {
            pendingHistory = nil
            open(conversationID: history.id, expectedNamespace: history.namespace)
            return
        }
        pendingHistory = nil
        guard !retired, let handoff = pendingNavigation, navigationTask == nil else {
            pendingNavigation?.cancel(); pendingNavigation = nil; return
        }
        pendingNavigation = nil
        navigationTask = Task { @MainActor [weak self] in
            guard let self else { return }
            defer { self.navigationTask = nil }
            do {
                let receipt = try await handoff.consume()
                try Task.checkCancellation()
                try receipt.validate(for: handoff.destination, session: handoff.session)
                guard !self.retired, receipt.presentationAcknowledged else { throw HanlinHostError.staleContext }
                self.navigationReceipt = receipt
                // A source button keeps the existing close-chat behavior. Do not
                // silently resume a model or transfer its former consent. A later
                // explicit chat opening uses the same saved conversation store.
                if let successor = receipt.successorSession { self.composition.closeHanlinHostSession(successor) }
                self.composition.closeHanlinHostSession(handoff.session)
            } catch {
                let observed = await handoff.host.navigationReceipt(for: handoff.requestID, session: handoff.session)
                if let successor = observed?.successorSession { self.composition.closeHanlinHostSession(successor) }
                self.composition.closeHanlinHostSession(handoff.session)
                if !self.retired {
                    self.manager?.alertMessage = .init(title: String(localized: "Source unavailable"),
                        message: String(localized: "The source could not be opened in the original study window."))
                }
            }
        }
    }

    func retire() {
        guard !retired else { return }
        retired = true
        if let presentation { nativeSession?.finishStudyChatPresentation(presentation.id) }
        navigationTask?.cancel(); navigationTask = nil
        pendingNavigation?.cancel(); pendingNavigation = nil; pendingHistory = nil
        pendingReadReopen?.consent?.revoke(); pendingReadReopen = nil; connectionAfterMount = nil
        requestClose()
    }
}

private struct OtzariaHanlinChatOwnerKey: EnvironmentKey {
    static let defaultValue: OtzariaHanlinChatOwner? = nil
}
extension EnvironmentValues {
    var otzariaHanlinChatOwner: OtzariaHanlinChatOwner? {
        get { self[OtzariaHanlinChatOwnerKey.self] }
        set { self[OtzariaHanlinChatOwnerKey.self] = newValue }
    }
}
#endif

#if os(iOS)
import SwiftUI
import HanlinChatUI
import HanlinScriptUI
import HanlinHostContracts
import HanlinPresentationKit
import HanlinRichUI

/// The actual native reader/global toolbar shares this scene's original owner.
struct OtzariaHanlinChatLaunchButton: View {
    let identifier: String
    @Environment(\.otzariaHanlinChatOwner) private var owner
    var body: some View {
        if let owner {
            Button { owner.open() } label: {
                Label(String(localized: "Study chat"), systemImage: "bubble.left.and.text.bubble.right")
            }
            .accessibilityIdentifier(identifier)
        }
    }
}

struct OtzariaHanlinChatPresentationHost: ViewModifier {
    let owner: OtzariaHanlinChatOwner?
    func body(content: Content) -> some View {
        let dismissedSessionID = owner?.presentation?.id
        return content
            .environment(\.otzariaHanlinChatOwner, owner)
            .sheet(isPresented: Binding(
                get: { owner?.isPresented == true && owner?.presentation?.id == dismissedSessionID },
                set: { [dismissedSessionID] in owner?.presentationBindingChanged($0, sessionID: dismissedSessionID) }),
                onDismiss: { [dismissedSessionID] in owner?.didDismiss(sessionID: dismissedSessionID) }) {
                    if let owner, let session = owner.presentation {
                        OtzariaHanlinChatView(session: session, owner: owner)
                    }
                }
    }
}

/// Composition of the canonical SDK layout, Markdown/OpenUI, tool activity,
/// Morph composer and native editor. There is no host renderer or agent loop.
private struct OtzariaHanlinChatView: View {
    @Bindable var session: OtzariaHanlinChatSession
    let owner: OtzariaHanlinChatOwner
    @State private var showsConnection = false
    @State private var expanded = false
    @State private var activePage: String?
    @State private var editorHeight: CGFloat = 38
    @State private var inputHeight: CGFloat = 52
    @State private var toolbarHeight: CGFloat = 0
    @State private var composerHeight: CGFloat = 70

    var body: some View {
        NavigationStack {
            VStack(spacing: 0) {
                if let scope = session.currentWorkReadScope {
                    VStack(alignment: .leading, spacing: 4) {
                        Text(String(localized: "Book search: \(scope.title)")).font(.subheadline)
                        Text(String(localized: "Otzaria. Matching excerpts may be shared with your connected model."))
                            .font(.caption).foregroundStyle(.secondary)
                        Button(String(localized: "End book access")) { owner.endCurrentWorkReadAccess(sessionID: session.id) }
                            .accessibilityIdentifier("otzaria-hanlin-end-book-access")
                    }
                    .frame(maxWidth: .infinity, alignment: .leading).padding(.horizontal).padding(.vertical, 8)
                    .accessibilityIdentifier("otzaria-hanlin-book-access")
                }
                if let error = session.errorMessage { HanlinChatErrorBanner(errorMessage: error) }
                if session.isConfigured || !session.messages.isEmpty || !session.draft.isEmpty {
                    GeometryReader { geometry in
                        HanlinChatView(shell: session.profile?.shell ?? .init(id: "hanlin.research", title: String(localized: "Study chat"))) {
                            transcript
                        } composer: {
                            composer(availableHeight: geometry.size.height)
                                .onGeometryChange(for: CGFloat.self) { $0.size.height } action: { composerHeight = $0 }
                        }
                    }
                } else {
                    OtzariaHanlinConnectionView(session: session)
                }
            }
            .navigationTitle(String(localized: "Study chat"))
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                if !session.isConfigured && (!session.messages.isEmpty || !session.draft.isEmpty) {
                    ToolbarItem(placement: .primaryAction) {
                        Button(String(localized: "Connect")) { showsConnection = true }
                            .accessibilityIdentifier("otzaria-hanlin-reconnect")
                    }
                }
                ToolbarItem(placement: .primaryAction) {
                    NavigationLink {
                        OtzariaHanlinHistoryView(owner: owner, currentID: session.identity.conversationID)
                    } label: {
                        Label(String(localized: "Conversations"), systemImage: "clock.arrow.circlepath")
                    }
                    .accessibilityIdentifier("otzaria-hanlin-history")
                }
                ToolbarItem(placement: .cancellationAction) {
                    Button(String(localized: "Close"), action: session.close)
                        .accessibilityIdentifier("otzaria-hanlin-close")
                }
            }
        }
        .sheet(isPresented: $showsConnection) {
            NavigationStack {
                VStack(spacing: 0) {
                    if let error = session.errorMessage { HanlinChatErrorBanner(errorMessage: error) }
                    OtzariaHanlinConnectionView(session: session)
                }
                .toolbar {
                    ToolbarItem(placement: .cancellationAction) {
                        Button(String(localized: "Close")) { showsConnection = false }
                    }
                }
            }
        }
        .onChange(of: session.isConfigured) { _, value in if value { showsConnection = false } }
        .background {
            ReaderSceneIdentityReader { sceneID in owner.didMount(sceneID: sceneID, sessionID: session.id) }
                .frame(width: 0, height: 0).accessibilityHidden(true)
        }
        .environment(\.openURL, OpenURLAction { url in
            if url.scheme?.lowercased() == "maktabah" {
                session.requestNavigation(url)
                return .handled
            }
            return ["https", "http"].contains(url.scheme?.lowercased() ?? "") ? .systemAction : .discarded
        })
        .accessibilityIdentifier("otzaria-hanlin-chat")
    }

    private var transcript: some View {
        ScrollViewReader { reader in
            ScrollView {
                LazyVStack(alignment: .leading, spacing: 16) {
                    ForEach(session.messages) { message in
                        VStack(alignment: .leading, spacing: 10) {
                            if message.role == "user" {
                                HanlinChatMessageBubble(message: message, presentationMode: .full)
                            } else if let state = session.messageStates[message.id] {
                                if let reasoning = session.reasoning[message.id], !reasoning.isEmpty {
                                    DisclosureGroup(String(localized: "Thinking"), isExpanded: Binding(
                                        get: { state.expandedActivityIDs.contains("reasoning") },
                                        set: { state.setExpanded($0, activityID: "reasoning") })) {
                                        HanlinMarkdownView(text: reasoning)
                                    }
                                    .disclosureGroupStyle(HanlinMotionDisclosureStyle())
                                }
                                ForEach(session.activities.filter { $0.messageID == message.id }) { activity in
                                    DisclosureGroup(isExpanded: Binding(
                                        get: { state.expandedActivityIDs.contains(activity.id) },
                                        set: { state.setExpanded($0, activityID: activity.id) })) {
                                        Text(activity.arguments).font(.system(.footnote, design: .monospaced)).textSelection(.enabled)
                                        if let result = activity.result { HanlinMarkdownView(text: result) }
                                    } label: {
                                        HanlinToolActivityHeader(title: activity.name, status: activity.status,
                                            symbol: "wrench.and.screwdriver", isActive: activity.isActive)
                                    }
                                    .disclosureGroupStyle(HanlinMotionDisclosureStyle())
                                }
                                ForEach(session.sources.filter { $0.messageID == message.id }) { source in
                                    Button {
                                        session.requestNavigation(source.destination)
                                    } label: {
                                        Label(String(localized: "Open source"), systemImage: "book")
                                    }
                                    .disabled(session.isStreaming || session.isNavigating)
                                    .accessibilityIdentifier("otzaria-hanlin-source-" + source.id.uuidString)
                                }
                                if message.content.isEmpty && session.isStreaming && message.id == session.messages.last?.id {
                                    ProgressView().accessibilityLabel(String(localized: "Thinking"))
                                }
                                ForEach(OpenUIInlineParts.split(message.content, identity: state.identity,
                                    catalogs: state.profile.catalogs.map(\.reference),
                                    isStreaming: session.isStreaming && message.id == session.messages.last?.id)) { part in
                                        switch part.payload {
                                        case .markdown(let text): HanlinMarkdownView(text: text)
                                        case .openUI:
                                            OpenUIBlock(part: part, state: state) { _ in
                                                // Native actions are not advertised by this read-only host.
                                                // Local renderer state uses the original message state owner.
                                                throw HanlinHostError.denied
                                            }
                                        }
                                    }
                            }
                        }
                        .id(message.id)
                    }
                }
                .padding()
                .padding(.bottom, composerHeight)
            }
            .scrollDismissesKeyboard(.interactively)
            .onChange(of: session.messages.last?.content) { _, _ in
                if let last = session.messages.last { reader.scrollTo(last.id, anchor: .bottom) }
            }
        }
    }

    private func composer(availableHeight: CGFloat) -> some View {
        let budget = max(38, HanlinMorphGeometry.editorBudget(availableHeight: availableHeight,
            accessoryHeight: 0, inputHeight: inputHeight, editorHeight: editorHeight,
            toolbarHeight: toolbarHeight, isExpanded: expanded))
        return HanlinMorphComposer(
            isExpanded: $expanded, activePage: $activePage, availableHeight: availableHeight, accessoryHeight: 0,
            title: { _ in String(localized: "Study chat") },
            subtitle: { _ in String(localized: "Conversation appearance") },
            backIdentifier: { _ in "otzaria-hanlin-composer-back" },
            onOpen: { expanded = true },
            onBackgroundTap: { expanded = false },
            onInputHeightChange: { inputHeight = $0 },
            onToolbarHeightChange: { toolbarHeight = $0 }) {
                Picker(String(localized: "Appearance"), selection: $session.selectedProfile) {
                    ForEach(session.presentationDescriptor.availableProfiles, id: \.reference) { profile in
                        Text(profile.shellID == "hanlin.research" ? String(localized: "Research") : String(localized: "Standard"))
                            .tag(profile.reference)
                    }
                }
                .disabled(session.isStreaming)
                .accessibilityIdentifier("otzaria-hanlin-profile-picker")
            } detail: { _ in
                EmptyView()
            } input: {
                HStack(alignment: .bottom, spacing: 10) {
                    NativeMultilineTextEditor(
                        text: Binding(
                            get: { [session] in session.draft },
                            set: { [session] in session.updateDraftFromEditor($0) }),
                        textHeight: $editorHeight,
                        placeholderText: String(localized: "Message"), maxHeight: budget,
                        usesAutomaticLineLimits: true, onSendMessage: session.send,
                        readCurrentTextState: { [session] in session.readCurrentDraftTextState() })
                        .frame(height: min(editorHeight, budget))
                        .accessibilityIdentifier("otzaria-hanlin-composer")
                    if session.isStreaming {
                        Button(action: session.stop) {
                            Image(systemName: "stop.circle.fill").font(.title)
                        }
                        .accessibilityLabel(String(localized: "Stop"))
                        .accessibilityIdentifier("otzaria-hanlin-stop")
                    } else {
                        HanlinChatSendButton(canSend: session.canSend, isStreaming: false,
                            presentationMode: .full, action: session.send)
                            .accessibilityIdentifier("otzaria-hanlin-send")
                    }
                }
                .padding(10)
            }
            .padding(12)
    }
}

private struct OtzariaHanlinConnectionView: View {
