                    .textInputAutocapitalization(.never).autocorrectionDisabled()
                    .accessibilityIdentifier("otzaria-hanlin-model")
                SecureField(String(localized: "API key"), text: $credential)
                    .textInputAutocapitalization(.never).autocorrectionDisabled()
                    .accessibilityIdentifier("otzaria-hanlin-api-key")
